private fun hkdfSha256(ikm: ByteArray, salt: ByteArray, info: ByteArray): ByteArray {
    val pseudorandomKey = hmacSha256(salt, ikm)
    return hmacSha256(pseudorandomKey, info + byteArrayOf(1)).copyOf(32)
}

private fun hmacSha256(key: ByteArray, message: ByteArray): ByteArray =
    Mac.getInstance("HmacSHA256").run {
        init(SecretKeySpec(key, "HmacSHA256"))
        doFinal(message)
    }

private fun aesGcmSeal(key: ByteArray, nonce: ByteArray, aad: ByteArray, plaintext: ByteArray): ByteArray =
    Cipher.getInstance("AES/GCM/NoPadding").run {
        init(Cipher.ENCRYPT_MODE, SecretKeySpec(key, "AES"), GCMParameterSpec(128, nonce))
        updateAAD(aad)
        doFinal(plaintext)
    }

private val p256Parameters: ECParameterSpec by lazy {
    AlgorithmParameters.getInstance("EC").run {
        init(ECGenParameterSpec("secp256r1"))
        getParameterSpec(ECParameterSpec::class.java)
    }
}

private fun ecPublicKey(raw: ByteArray): PublicKey {
    require(raw.size == 65 && raw[0] == 4.toByte())
    val point = ECPoint(
        BigInteger(1, raw.copyOfRange(1, 33)),
        BigInteger(1, raw.copyOfRange(33, 65)),
    )
    return KeyFactory.getInstance("EC").generatePublic(ECPublicKeySpec(point, p256Parameters))
}

private fun ecPrivateKey(raw: ByteArray) =
    KeyFactory.getInstance("EC").generatePrivate(
        ECPrivateKeySpec(BigInteger(1, raw), p256Parameters),
    )

private data class HpkeVector(
    val sharedSecret: ByteArray,
    val key: ByteArray,
    val baseNonce: ByteArray,
    val ciphertext: ByteArray,
)

private fun hpkeSealVector(
    recipientPublicKey: ByteArray,
    ephemeralPrivateKey: ByteArray,
    encapsulatedKey: ByteArray,
    info: ByteArray,
    aad: ByteArray,
    plaintext: ByteArray,
): HpkeVector {
    val kemSuite = "KEM".encodeToByteArray() + i2osp(0x10, 2)
    val hpkeSuite = "HPKE".encodeToByteArray() + i2osp(0x10, 2) + i2osp(1, 2) + i2osp(2, 2)
    val dh = KeyAgreement.getInstance("ECDH").run {
        init(ecPrivateKey(ephemeralPrivateKey))
        doPhase(ecPublicKey(recipientPublicKey), true)
        generateSecret()
    }
    val eaePrk = labeledExtract(kemSuite, byteArrayOf(), "eae_prk", dh)
    val sharedSecret = labeledExpand(
        kemSuite,
        eaePrk,
        "shared_secret",
        encapsulatedKey + recipientPublicKey,
        32,
    )
    val pskIdHash = labeledExtract(hpkeSuite, byteArrayOf(), "psk_id_hash", byteArrayOf())
    val infoHash = labeledExtract(hpkeSuite, byteArrayOf(), "info_hash", info)
    val context = byteArrayOf(0) + pskIdHash + infoHash
    val secret = labeledExtract(hpkeSuite, sharedSecret, "secret", byteArrayOf())
    val key = labeledExpand(hpkeSuite, secret, "key", context, 32)
    val baseNonce = labeledExpand(hpkeSuite, secret, "base_nonce", context, 12)
    return HpkeVector(sharedSecret, key, baseNonce, aesGcmSeal(key, baseNonce, aad, plaintext))
}

private fun labeledExtract(suite: ByteArray, salt: ByteArray, label: String, ikm: ByteArray): ByteArray =
    hkdfExtract(salt, "HPKE-v1".encodeToByteArray() + suite + label.encodeToByteArray() + ikm)

private fun labeledExpand(
    suite: ByteArray,
    pseudorandomKey: ByteArray,
    label: String,
    info: ByteArray,
    length: Int,
): ByteArray = hkdfExpand(
    pseudorandomKey,
    i2osp(length, 2) + "HPKE-v1".encodeToByteArray() + suite + label.encodeToByteArray() + info,
    length,
)

private fun hkdfExtract(salt: ByteArray, ikm: ByteArray): ByteArray =
    hmacSha256(if (salt.isEmpty()) ByteArray(32) else salt, ikm)

private fun hkdfExpand(pseudorandomKey: ByteArray, info: ByteArray, length: Int): ByteArray {
    var output = byteArrayOf()
    var previous = byteArrayOf()
    var counter = 1
    while (output.size < length) {
        previous = hmacSha256(pseudorandomKey, previous + info + byteArrayOf(counter.toByte()))
        output += previous
        counter += 1
    }
    return output.copyOf(length)
}

private fun i2osp(value: Int, length: Int): ByteArray =
    ByteArray(length) { index -> (value ushr (8 * (length - index - 1))).toByte() }

private fun decodeBase64Url(value: String): ByteArray =
    Base64.getUrlDecoder().decode(value)

private fun encodeBase64Url(value: ByteArray): String =
    Base64.getUrlEncoder().withoutPadding().encodeToString(value)

private fun canonicalJson(value: JsonElement): String = when (value) {
    is JsonObject -> value.entries.sortedBy { it.key }.joinToString(",", "{", "}") {
        "${JsonPrimitive(it.key)}:${canonicalJson(it.value)}"
    }
    is JsonArray -> value.joinToString(",", "[", "]") { canonicalJson(it) }
    else -> value.toString()
}

private class Draft07Subset(private val root: JsonObject) {
    fun valid(instance: JsonElement, rawSchema: JsonElement): Boolean {
        val schema = rawSchema as? JsonObject ?: return true
        schema["\$ref"]?.jsonPrimitive?.contentOrNull?.let { reference ->
            return valid(instance, resolve(reference))
        }
        schema["oneOf"]?.jsonArray?.let { branches ->
            if (branches.count { valid(instance, it) } != 1) return false
        }
        schema["const"]?.let { if (instance != it) return false }
        schema["enum"]?.jsonArray?.let { if (instance !in it) return false }
        schema["type"]?.let { type ->
            val types = if (type is JsonArray) type.mapNotNull { it.jsonPrimitive.contentOrNull }
            else listOf(type.jsonPrimitive.content)
            if (types.none { matchesType(instance, it) }) return false
        }

        if (instance is JsonObject) {
            schema["x-curfew-derived-campaign-duration"]?.jsonObject?.let { rule ->
                val attempts = instance[rule.getValue("attemptsProperty").jsonPrimitive.content]
                    ?.jsonPrimitive?.longOrNull ?: return false
                val ringing = instance[rule.getValue("ringProperty").jsonPrimitive.content]
                    ?.jsonPrimitive?.longOrNull ?: return false
                val quiet = instance[rule.getValue("quietProperty").jsonPrimitive.content]
                    ?.jsonPrimitive?.longOrNull ?: return false
                val declaredDuration = instance[rule.getValue("durationProperty").jsonPrimitive.content]
                    ?.jsonPrimitive?.longOrNull
                    ?: return false
                val cap = rule.getValue("capSeconds").jsonPrimitive.long
                val computed = attempts * ringing + maxOf(0, attempts - 1) * quiet
                if (computed != declaredDuration || computed > cap) return false
            }
            val required = schema["required"]?.jsonArray
                ?.map { it.jsonPrimitive.content }
                .orEmpty()
            if (!instance.keys.containsAll(required)) return false
            val properties = schema["properties"] as? JsonObject
            if (schema["additionalProperties"]?.jsonPrimitive?.booleanOrNull == false &&
                properties != null && instance.keys.any { it !in properties }) return false
            properties?.forEach { (name, propertySchema) ->
                instance[name]?.let { if (!valid(it, propertySchema)) return false }
            }
        }

        if (instance is JsonArray) {
            schema["minItems"]?.jsonPrimitive?.intOrNull?.let { if (instance.size < it) return false }
            schema["maxItems"]?.jsonPrimitive?.intOrNull?.let { if (instance.size > it) return false }
            if (schema["uniqueItems"]?.jsonPrimitive?.booleanOrNull == true &&
                instance.distinct().size != instance.size) return false
            schema["items"]?.let { itemSchema ->
                if (instance.any { !valid(it, itemSchema) }) return false
            }
        }

        if (instance is JsonPrimitive && instance.isString) {
            val value = instance.content
            schema["minLength"]?.jsonPrimitive?.intOrNull?.let { if (value.length < it) return false }
            schema["maxLength"]?.jsonPrimitive?.intOrNull?.let { if (value.length > it) return false }
            schema["pattern"]?.jsonPrimitive?.contentOrNull?.let {
                if (!Regex(it).containsMatchIn(value)) return false
            }
            if (schema["format"]?.jsonPrimitive?.contentOrNull == "uri") {
                if (runCatching { URI(value) }.getOrNull()?.isAbsolute != true) return false
            }
        }

        if (instance is JsonPrimitive && !instance.isString) {
            instance.doubleOrNull?.let { number ->
                schema["minimum"]?.jsonPrimitive?.doubleOrNull?.let { if (number < it) return false }
                schema["maximum"]?.jsonPrimitive?.doubleOrNull?.let { if (number > it) return false }
            }
        }
        return true
    }

    private fun resolve(reference: String): JsonElement {
        require(reference.startsWith("#/")) { "Only local refs are used in golden vectors" }
        return reference.removePrefix("#/").split('/').fold(root as JsonElement) { node, segment ->
            node.jsonObject.getValue(segment.replace("~1", "/").replace("~0", "~"))
        }
    }

    private fun matchesType(instance: JsonElement, type: String): Boolean = when (type) {
        "null" -> instance is JsonNull
        "object" -> instance is JsonObject
        "array" -> instance is JsonArray
        "string" -> instance is JsonPrimitive && instance.isString
        "boolean" -> instance is JsonPrimitive && instance.booleanOrNull != null
        "integer" -> instance is JsonPrimitive && !instance.isString && instance.longOrNull != null
        "number" -> instance is JsonPrimitive && !instance.isString && instance.doubleOrNull != null
        else -> true
    }
}
